import{_ as a,o as s,c as t,a6 as i}from"./chunks/framework.4tsfTCyC.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"TeXRA","text":"Reliable Multi-Agent AI for Theorists","tagline":"Agents that search, derive, calculate, compile, and verify — built for work where correctness is non-negotiable.","image":{"src":"/logo-1024x1024.svg","alt":"TeXRA Logo"},"actions":[{"theme":"brand","text":"Get Started","link":"/guide/"},{"theme":"alt","text":"Install from Marketplace","link":"vscode:extension/texra-ai.texra"}]},"features":[{"icon":"🔬","title":"Grounded, not generative","details":"Every citation from a real database. Every figure compiled. Every diff reviewable."},{"icon":"🔁","title":"Agents that reflect","details":"Plan, execute, self-critique, revise — the same loop a careful collaborator follows."},{"icon":"🛡️","title":"Three levels of verification","details":"LLM prose, Wolfram algebra, Lean 4 formal proof — connected in one environment."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function o(l,e,d,n,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<section class="architecture-section"><h2>Multi-agent orchestration</h2><div class="lifecycle"><div class="lifecycle-phase"><div class="phase-icon phase-explore"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><path d="M21 21l-4.35-4.35"></path></svg></div><div class="phase-name">Explore</div><div class="phase-agents">search</div><div class="phase-desc">arXiv, Crossref</div></div><div class="lifecycle-arrow"><svg width="28" height="16" viewBox="0 0 28 16"><path d="M0 8h24M18 2l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"></path></svg></div><div class="lifecycle-phase"><div class="phase-icon phase-derive"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 016.5 17H20"></path><path d="M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z"></path></svg></div><div class="phase-name">Derive</div><div class="phase-agents">research · lean</div><div class="phase-desc">Wolfram, Lean, bash</div></div><div class="lifecycle-arrow"><svg width="28" height="16" viewBox="0 0 28 16"><path d="M0 8h24M18 2l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"></path></svg></div><div class="lifecycle-phase"><div class="phase-icon phase-verify"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 12l2 2 4-4"></path><path d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg></div><div class="phase-name">Verify</div><div class="phase-agents">review · lean</div><div class="phase-desc">Wolfram checks, Lean proofs</div></div><div class="lifecycle-arrow"><svg width="28" height="16" viewBox="0 0 28 16"><path d="M0 8h24M18 2l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"></path></svg></div><div class="lifecycle-phase"><div class="phase-icon phase-write"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"></path><path d="M16.5 3.5a2.121 2.121 0 013 3L7 19l-4 1 1-4L16.5 3.5z"></path></svg></div><div class="phase-name">Write</div><div class="phase-agents">polish · correct · draw</div><div class="phase-desc">LaTeX, figures, diffs</div></div><div class="lifecycle-arrow"><svg width="28" height="16" viewBox="0 0 28 16"><path d="M0 8h24M18 2l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"></path></svg></div><div class="lifecycle-phase"><div class="phase-icon phase-present"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect><path d="M8 21h8M12 17v4"></path></svg></div><div class="phase-name">Present</div><div class="phase-agents">paper2slide</div><div class="phase-desc">Beamer, poster</div></div></div><div class="feedback-loop"><svg width="100%" height="32" viewBox="0 0 600 32" preserveAspectRatio="xMidYMid meet"><defs><marker id="arrowL" markerWidth="8" markerHeight="6" refX="8" refY="3" orient="auto"><path d="M8 0L0 3 8 6" fill="var(--vp-c-danger-1)"></path></marker></defs><path d="M390 4C390 22 210 22 210 4" fill="none" stroke="var(--vp-c-danger-1)" stroke-width="1.5" stroke-dasharray="5 3" marker-start="url(#arrowL)"></path><text x="300" y="28" text-anchor="middle" fill="var(--vp-c-danger-1)" font-size="10" font-weight="500">fix errors</text></svg></div><div class="paradigms"><div class="paradigm paradigm-workflow"><div class="paradigm-label">Workflow Agents</div><div class="paradigm-flow"><span class="pf-node">Read project</span><span class="pf-edge">→</span><span class="pf-node">Plan</span><span class="pf-edge">→</span><span class="pf-node">Draft</span></div><div class="paradigm-flow"><span class="pf-node pf-reflect">Reflect</span><span class="pf-edge">→</span><span class="pf-node">Output</span></div><div class="paradigm-io">.tex in → improved .tex + latexdiff</div></div><div class="paradigm-orchestrator"><div class="orch-icon"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"></path><circle cx="8.5" cy="7" r="4"></circle><path d="M20 8v6M23 11h-6"></path></svg></div><div class="orch-label">Orchestrator</div><div class="orch-desc">Breaks work into sub-tasks, delegates to specialized agents, coordinates results</div></div><div class="paradigm paradigm-tooluse"><div class="paradigm-label">Tool-Use Agents</div><div class="paradigm-flow"><span class="pf-node">Your question</span><span class="pf-edge">→</span><span class="pf-node">Tool calls</span><span class="pf-edge">→</span><span class="pf-node">Reason</span></div><div class="paradigm-flow"><span class="pf-node pf-reflect">Answer</span></div><div class="paradigm-io">Conversational · persistent across sessions</div></div></div><div class="tools-bar"><span class="tool-tag">wolfram</span><span class="tool-tag">lean</span><span class="tool-tag">arxiv</span><span class="tool-tag">bash</span><span class="tool-tag">web</span><span class="tool-tag">zotero</span><span class="tool-tag">read</span><span class="tool-tag">write</span><span class="tool-tag">grep</span><span class="tool-more">25+ built-in tools</span></div></section><section class="use-cases"><h2>How researchers use TeXRA</h2><div class="cases-grid"><div class="case-card"><span class="case-label">Derive</span><h3>Steady-state entanglement in a driven spin chain</h3><p>The <code>research</code> agent builds the Lindblad superoperator, solves for the steady state in Wolfram, computes the concurrence analytically, and cross-checks with exact diagonalization in Julia at N=8.</p></div><div class="case-card"><span class="case-label">Write</span><h3>Finalizing a 40-page paper on spectral graph theory</h3><p>The <code>correct</code> agent unifies notation — <code>\\lambda_2</code> vs <code>\\mu</code> for the same eigenvalue across sections — fixes label conflicts, and outputs a diff you review line by line.</p></div><div class="case-card"><span class="case-label">Verify</span><h3>Formalizing subadditivity of entropy in Lean 4</h3><p>The <code>lean</code> agent searches Loogle for the right Mathlib lemma, reads the proof state, adds a missing hypothesis, and produces a proof that compiles with zero errors.</p></div></div></section><section class="bottom-cta"><h2>Start in under two minutes</h2><p>Install from the VS Code Marketplace, add an API key, and run your first agent.</p><div class="cta-buttons"><a href="/guide/quick-start" class="cta-button cta-primary">Quick Start Guide</a><a href="/guide/built-in-agents" class="cta-button cta-secondary">Browse All Agents</a></div></section><section class="faq-section"><h2>Common questions</h2><details><summary>What models does it support?</summary><p>Claude, GPT, Gemini, DeepSeek, Grok, and more via OpenRouter. Bring your own API key, or sign in for free researcher access.</p></details><details><summary>Does it work with Overleaf?</summary><p>Yes — via git sync. See the <a href="/guide/working-with-overleaf">Overleaf guide</a>.</p></details><details><summary>Does it work with Lean 4?</summary><p>Yes — Loogle search, proof state inspection, diagnostics, build and cache management. Requires the Lean 4 extension.</p></details><details><summary>Is my data private?</summary><p>All API calls go directly from your machine to the model provider. No TeXRA servers in the middle.</p></details><details><summary>Can I build custom agents?</summary><p>Yes — agents are YAML files you can modify or create from scratch. See <a href="/guide/custom-agents">Custom Agents</a>.</p></details><details><summary>Where do I get help?</summary><p>Email <a href="mailto:contact@texra.ai">contact@texra.ai</a> or open an issue on <a href="https://github.com/texra-ai/texra-issues">GitHub</a>.</p></details></section>',4)])])}const g=a(r,[["render",o]]);export{v as __pageData,g as default};
